content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-05-agenda-005

=== 用户原始指令 (query.txt) ===
做个提醒卡 点了能跳到日历app 能读下天气 还要提示我快迟到了

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "做个提醒卡 点了能跳到日历app 能读下天气 还要提示我快迟到了",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "ViewCalendarEvent",
        "params": {
          "entityId": "agenda_20260709_001"
        }
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "下一条日程的唯一标识，用于打开日程详情。",
              "sampleValue": "agenda_20260709_001"
            },
            "title": {
              "type": "string",
              "description": "下一条日程标题。",
              "sampleValue": "产品评审"
            },
            "dtStart": {
              "type": "string",
              "description": "下一条日程开始时间，今天内使用 HH:MM 展示。",
              "sampleValue": "09:30"
            },
            "dtEnd": {
              "type": "string",
              "description": "下一条日程结束时间，今天内使用 HH:MM 展示。",
              "sampleValue": "10:00"
            }
          }
        ]
      },
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询地区名称。",
            "sampleValue": "当前位置"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本。",
            "sampleValue": "28°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "多云"
          }
        }
      }
    },
    "ui": {
      "cardTitle": {
        "type": "string",
        "description": "卡片标题，提示当前是日程提醒。",
        "sampleValue": "日程提醒"
      },
      "lateWarning": {
        "type": "string",
        "description": "迟到风险提示文本。",
        "sampleValue": "快迟到了"
      },
      "weatherLabel": {
        "type": "string",
        "description": "天气信息前缀标签。",
        "sampleValue": "天气"
      },
      "actionLabel": {
        "type": "string",
        "description": "打开日历详情的动作标签。",
        "sampleValue": "看日历"
      }
    },
    "asset": {
      "calendarIcon": {
        "type": "string",
        "description": "日程提醒图标资源路径。",
        "sampleValue": "resources/base/media/calendar_fill.svg"
      },
      "weatherIcon": {
        "type": "string",
        "description": "天气支撑信息图标资源路径。",
        "sampleValue": "resources/base/media/cloudy.png"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/calendar_fill.svg",
      "description": "黑色日历实心图标，适合用于日程管理、日历事件查看和当日安排识别。"
    },
    {
      "src": "resources/base/media/cloudy.png",
      "description": "彩色云朵天气图标，适合用于多云天气和出行前天气提示。"
    }
  ]
}

=== 待评审 DSL (card.dsl.jsonl，共 3 行) ===
{"version":"v0.9","createSurface":{"surfaceId":"surface_card","catalogId":"ohos.a2ui.extended.catalog","width":140,"height":140}}
{"version":"v0.9","updateComponents":{"surfaceId":"surface_card","root":"root","components":[{"id":"root","component":"Column","children":["header_row","event_title","time_text","divider_line","weather_row","action_button"],"itemMargin":2,"styles":{"width":140,"height":140,"padding":12,"borderRadius":18,"clip":true,"justifyContent":"start","alignItems":"center","backgroundColor":"#ffffffff"}},{"id":"header_row","component":"Row","children":["calendar_icon","card_title"],"itemMargin":6,"styles":{"width":116,"height":16,"justifyContent":"start","alignItems":"center"}},{"id":"calendar_icon","component":"Image","src":"{{ ${/asset/calendarIcon} }}","styles":{"width":14,"height":14,"objectFit":"contain"}},{"id":"card_title","component":"Text","content":"{{ ${/ui/cardTitle} }}","styles":{"width":96,"height":14,"fontSize":12,"fontWeight":600,"fontColor":"#99000000","maxLines":1,"textOverflow":"none","textAlign":"start"}},{"id":"event_title","component":"Text","content":"{{ ${/data/calendar/items/0/title} }}","styles":{"width":116,"height":18,"fontSize":16,"fontWeight":700,"fontColor":"#e5000000","maxLines":1,"textOverflow":"none","textAlign":"center"}},{"id":"time_text","component":"Text","content":"{{ ${/data/calendar/items/0/dtStart} + '-' + ${/data/calendar/items/0/dtEnd} + ' ' + ${/ui/lateWarning} }}","styles":{"width":116,"height":16,"fontSize":12,"fontWeight":600,"fontColor":"#ffe84026","maxLines":1,"textOverflow":"none","textAlign":"center"}},{"id":"divider_line","component":"Divider","styles":{"width":116,"height":1,"strokeWidth":1,"vertical":false,"color":"#33000000"}},{"id":"weather_row","component":"Row","children":["weather_icon","weather_text"],"itemMargin":6,"styles":{"width":116,"height":16,"justifyContent":"center","alignItems":"center"}},{"id":"weather_icon","component":"Image","src":"{{ ${/asset/weatherIcon} }}","styles":{"width":14,"height":14,"objectFit":"contain"}},{"id":"weather_text","component":"Text","content":"{{ ${/ui/weatherLabel} + ' ' + ${/data/weather/current/condition} + ' ' + ${/data/weather/current/temperatureText} }}","styles":{"width":96,"height":14,"fontSize":12,"fontWeight":500,"fontColor":"#99000000","maxLines":1,"textOverflow":"none","textAlign":"start"}},{"id":"action_button","component":"Button","label":"{{ ${/ui/actionLabel} }}","onClick":[{"call":"clickToIntent","args":{"intentName":"ViewCalendarEvent","params":{"entityId":"{{ ${/data/calendar/items/0/entityId} }}"}}}],"styles":{"width":72,"height":28,"borderRadius":14,"backgroundColor":"#ff0a59f7","fontSize":12,"fontWeight":"medium","fontColor":"#ffffffff"}}]}}
